// Adapted from ww6 src/services/allocationEngineService.ts:43-104 @ 09751ce (Prisma and money removed),
// ported to Java: rule matching by tag and the run summary the report shows.
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

record Rule(String matchTagKey, String matchTagValue) {}

record Summary(int evaluatedLineItems, int matchedRules, int unmatchedLineItems) {}

final class AllocationSummary {
    static boolean tagsMatch(String key, String value, Map<String, String> tags) {
        return tags.containsKey(key) && value.equals(tags.get(key));
    }

    static Summary computeSummary(List<Map<String, String>> costItemTags, List<Rule> rules) {
        Set<Rule> matched = new LinkedHashSet<>();
        int unmatchedLineItems = 0;
        for (Map<String, String> tags : costItemTags) {
            List<Rule> hits = rules.stream().filter(r -> tagsMatch(r.matchTagKey(), r.matchTagValue(), tags)).toList();
            if (hits.isEmpty()) unmatchedLineItems += 1;
            matched.addAll(hits);
        }
        return new Summary(costItemTags.size(), matched.size(), unmatchedLineItems);
    }
}

