class KataTest {
    public static void main(String[] args) {
        bootcamp.Check.test("every cost item is evaluated", () -> bootcamp.Check.eq(AllocationSummary.computeSummary(List.of(Map.of("team", "core"), Map.of("team", "core"), Map.of("env", "prod")), List.of(new Rule("team", "core"), new Rule("team", "web"), new Rule("project", "x"))).evaluatedLineItems(), 3));
        bootcamp.Check.test("an item no rule matches is unmatched", () -> bootcamp.Check.eq(AllocationSummary.computeSummary(List.of(Map.of("team", "core"), Map.of("team", "core"), Map.of("env", "prod")), List.of(new Rule("team", "core"), new Rule("team", "web"), new Rule("project", "x"))).unmatchedLineItems(), 1));
        System.exit(bootcamp.Check.report());
    }
}
